PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL,sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history(project_id TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL,sha256 TEXT NOT NULL,event TEXT NOT NULL,PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,action TEXT NOT NULL,fingerprint TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,created TEXT NOT NULL,revision INTEGER NOT NULL,result TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS objects(sha256 TEXT PRIMARY KEY,bytes INTEGER NOT NULL,private INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,result TEXT NOT NULL);
